package com.bank.semantics.core;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// The output side: account balances + a set of applied message ids (for idempotency).
public class Ledger {
    private static final Logger log = Logger.getLogger(Ledger.class.getName());
    private final Map<String, BigDecimal> balances = new HashMap<>();
    private final Set<String> appliedMsgIds = new HashSet<>();

    public void open(String id, BigDecimal opening) { balances.put(id, opening); }
    public BigDecimal balance(String id) { return balances.get(id); }

    // Plain apply (not idempotent) — used by at-most/at-least-once.
    public void debit(String accountId, BigDecimal amount) {
        balances.merge(accountId, amount.negate(), BigDecimal::add);
        log.info(() -> "debit " + amount + " → balance " + balances.get(accountId));
    }

    // Idempotent apply keyed by msgId — used by exactly-once.
    public void debitOnce(String msgId, String accountId, BigDecimal amount) {
        if (!appliedMsgIds.add(msgId)) {
            log.warning(() -> "SKIP duplicate msg " + msgId + " (idempotent)");
            return;
        }
        balances.merge(accountId, amount.negate(), BigDecimal::add);
        log.info(() -> "debitOnce " + amount + " → balance " + balances.get(accountId));
    }
}
