package com.bank.semantics.core;

import com.bank.semantics.model.DebitMsg;
import java.util.logging.Logger;

// AT-MOST-ONCE: commit offset BEFORE processing → may lose on crash, never duplicate.
public class AtMostOnce {
    private static final Logger log = Logger.getLogger(AtMostOnce.class.getName());
    private long committedOffset = -1;

    public void handle(DebitMsg m, Ledger ledger, boolean crashDuringProcessing) {
        committedOffset = m.getOffset(); // committed first
        if (crashDuringProcessing) {
            log.severe("CRASH after commit, before processing → message LOST");
            return; // on restart, offset already past → skipped
        }
        ledger.debit(m.getAccountId(), m.getAmount());
    }
}
