package com.bank.semantics.core;

import com.bank.semantics.model.DebitMsg;
import java.util.logging.Logger;

// AT-LEAST-ONCE: commit offset AFTER processing → never lose, may duplicate on crash.
public class AtLeastOnce {
    private static final Logger log = Logger.getLogger(AtLeastOnce.class.getName());

    public void handle(DebitMsg m, Ledger ledger, boolean crashBeforeCommit) {
        ledger.debit(m.getAccountId(), m.getAmount()); // processed
        if (crashBeforeCommit) {
            log.severe("CRASH after processing, before commit → will REPROCESS on restart");
            ledger.debit(m.getAccountId(), m.getAmount()); // replay applies it AGAIN (duplicate!)
        }
    }
}
