package com.bank.semantics.core;

import com.bank.semantics.model.DebitMsg;
import java.util.logging.Logger;

// EXACTLY-ONCE: idempotent apply by msgId + offset committed atomically with output.
public class ExactlyOnce {
    private static final Logger log = Logger.getLogger(ExactlyOnce.class.getName());

    public void handle(DebitMsg m, Ledger ledger, boolean crashBeforeCommit) {
        ledger.debitOnce(m.getMsgId(), m.getAccountId(), m.getAmount()); // idempotent
        if (crashBeforeCommit) {
            log.severe("CRASH before atomic commit → replay will retry the SAME msgId");
            ledger.debitOnce(m.getMsgId(), m.getAccountId(), m.getAmount()); // deduped → no double
        }
    }
}
