package com.bank.semantics;

import com.bank.semantics.core.*;
import com.bank.semantics.model.DebitMsg;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class SemanticsDemo {
    private static final Logger log = Logger.getLogger(SemanticsDemo.class.getName());

    public static void main(String[] args) {
        BigDecimal opening = new BigDecimal("1000000.00");
        DebitMsg msg = new DebitMsg("M1", 10, "SAV2001", new BigDecimal("50000.00"));

        log.info("=== AT-MOST-ONCE (crash loses the debit) ===");
        Ledger l1 = new Ledger(); l1.open("SAV2001", opening);
        new AtMostOnce().handle(msg, l1, true);
        log.info("Rajesh balance = " + l1.balance("SAV2001") + " (debit lost)");

        log.info("=== AT-LEAST-ONCE (crash duplicates the debit) ===");
        Ledger l2 = new Ledger(); l2.open("SAV2001", opening);
        new AtLeastOnce().handle(msg, l2, true);
        log.info("Rajesh balance = " + l2.balance("SAV2001") + " (debited TWICE — wrong)");

        log.info("=== EXACTLY-ONCE (crash is safe) ===");
        Ledger l3 = new Ledger(); l3.open("SAV2001", opening);
        new ExactlyOnce().handle(msg, l3, true);
        log.info("Rajesh balance = " + l3.balance("SAV2001") + " (debited exactly once — correct)");
    }
}
